local Buildings = require("constants.buildings")

-- generated by the Blender export, see sosciencity-blender-tools
local sprites = require("__sosciencity-graphics__.graphics.entity.atelier.sprite-data")

Tirislib.Item.create {
    type = "item",
    name = "atelier",
    icon = Tirislib.Prototype.placeholder_icon,
    icon_size = 64,
    subgroup = "sosciencity-infrastructure",
    order = "aab",
    place_result = "atelier",
    stack_size = Sosciencity.Config.building_stacksize,
    pictures = Sosciencity.Config.blueprint_on_belt
}

Tirislib.RecipeGenerator.create {
    results = {
        {type = "item", name = "atelier", amount = 1}
    },
    ingredients = {
        {theme = "building", amount = 1},
        {type = "item", name = "architectural-concept", amount = 1}
    },
    unlock = "atelier"
}

Tirislib.Entity.create {
    type = "assembling-machine",
    name = "atelier",
    flags = {"placeable-neutral", "player-creation"},
    minable = {mining_time = 0.5, result = "atelier"},
    max_health = 200,
    corpse = "small-remnants",
    vehicle_impact_sound = {filename = "__base__/sound/car-metal-impact.ogg", volume = 0.65},
    repair_sound = {filename = "__base__/sound/manual-repair-simple.ogg"},
    open_sound = {filename = "__base__/sound/machine-open.ogg", volume = 0.85},
    close_sound = {filename = "__base__/sound/machine-close.ogg", volume = 0.75},
    allowed_effects = {"productivity", "speed"},
    graphics_set = {
        animation = Tirislib.Entity.create_animation_from_sprite_data(sprites.static)
    },
    crafting_speed = 1,
    crafting_categories = {"sosciencity-atelier"},
    energy_usage = "60kW",
    energy_source = {
        type = "electric",
        usage_priority = "secondary-input",
        emissions_per_minute = {pollution = 0.15},
        drain = "0W"
    }
}:set_size(6, 6):copy_icon_from_item()
Sosciencity.configure_building("atelier")

-- The focus corner on the roof shows what the artists are working on: the control stage draws the variant of
-- the active recipe on top of the atelier (see Subentities.update_recipe_visualisation).
local visualisation = Buildings.values["atelier"].recipe_visualisation
for variant in pairs(Buildings.get_recipe_visualisation_variants(visualisation)) do
    for map, sheet in pairs(sprites[variant].maps) do
        if Buildings.recipe_visualisation_maps[map] then
            Tirislib.Prototype.create {
                type = "sprite",
                name = Buildings.get_recipe_visualisation_sprite("atelier", variant, map),
                filename = sheet.filenames[1],
                width = sheet.width,
                height = sheet.height,
                shift = sheet.shift,
                scale = 0.5
            }
        end
    end
end
